window.VD=window.VD||{};window.VD["vw/transport-t4-t5"]={"transporter-t4-confirmation-of-vehicle-unlocking-turn-signals":"<p><strong>Purpose </strong>: activates turn signals when vehicle is unlocked.  </p>\n<p><strong>roceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>35 – Centr.Verr.</strong>.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 02</strong></p>\n<p>Set the value to <strong>1</strong></p>","transporter-t4-vehicle-lock-confirmation-turn-signals":"<p><strong>Purpose </strong>: activates turn signals when vehicle is locked.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>35 – Centr.Verr.</strong>.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong></p>\n<p>Set the value to <strong>1</strong></p>","transporter-t4-t5-change-odb-language":"<p><strong>Purpose </strong>: To change the language of the ODB. (Highline MFA T4/T5)  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong></p>\n<p><em>Set the value according to the selected language</em></p>\n<p><em>1 = German</em><br/><em>2 = English</em><br/><em>3 = French</em><br/><em>4 = Italian</em><br/><em>5 = Spanish</em><br/><em>6 = Portuguese</em></p>","transporter-t4-t5-cruise-control-activation-retrofit":"<p><strong>Purpose:</strong> Enables the cruise control system after a retrofit installation (T4/T5 retrofit).</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>01 – Motor</strong> “.</p>\n<p><strong>4</strong> – Click on “<strong>Access – 11</strong>” then enter the code “<strong><em><strong>11463</strong></em></strong>”  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur2-6871f13e.webp\"/></figure>","transporter-t4-t5-deactivate-windshield-washer-indicator":"<p><strong>Purpose </strong>: to deactivate the windshield washer indicator on the ODB (on-board computer). (Model T4/T5 after 2000)  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><em>The first two digits of the code (<strong>??</strong>xxxx) are used to modify the Instrument module options. To remove the ice-washer indicator, subtract <strong>04</strong> from these digits. </em><br/><em>Example of initial coding (with washer indicator): <strong>05142</strong></em><br/><em>To remove the windscreen washer indicator, simply recode as follows: <strong>01142</strong> (05 – 04 = 01)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-920-820-E_Module17_Coding-de79aff6.webp\"/></figure>\n<p>To activate the ice washer indicator: +04</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","transporter-t4-t5-delete-belt-alarm":"<p><strong>Purpose </strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><em>The first two digits of the code (<strong>??</strong>xxxx) are used to modify the Instrument module options. To suppress the belt alarm, subtract <strong>2</strong> from these digits. </em><br/><em>Example of initial coding (with belt alarm): <strong>03142</strong></em><br/><em>To delete the belt alarm, simply recode as follows: <strong>01142</strong> (03 – 02 = 01)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-920-820-E_Module17_Coding-de79aff6.webp\"/></figure>\n<p><em>To activate the belt alarm: +02</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","transporter-t5-automatic-door-locks":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose </strong>: To configure automatic door locking at speeds over 15 km/h.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 03 </strong>(“Auto-Lock” in drop-down list)</p>\n<p>Set the value to <strong>1</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel03-eb379503.webp\"/></figure>","transporter-t5-automatic-door-unlocking":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose </strong>: to configure automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 04 </strong>(“Auto-Unlock” in drop-down list)</p>\n<p>Set the value to <strong>1</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel04-e2e3b584.webp\"/></figure>","transporter-t5-confirmation-of-vehicle-unlocking-turn-signals":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose </strong>: activates turn signals when vehicle is unlocked.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 08 </strong>(“Unlocking Confirmation (Blink)” in the drop-down list)</p>\n<p>Set the value to <strong>1</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel08-2de32bca.webp\"/></figure>","transporter-t5-mirror-defrost-duration":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose</strong>: Selects the duration of mirror defrosting.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select</strong> ” then click on ” <strong>09 – Centrale Elec.</strong>.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> (“Mirror Heating Activation Time” in the drop-down list)</p>\n<p><em>Set a value between <strong>1</strong> and <strong>254</strong> (from 0.66 min to 173 min)</em><br/><em>Default value (until April 2002) is <strong>29</strong> (20 min)</em><br/><em>Default value (since April 2002) is <strong>254</strong> (allows defrost to run all the time)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q1-937-049-C_Module09_Adaptation_Channel03-b676ef56.webp\"/></figure>","transporter-t5-key-configuration":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to program the remote controls that will be used with the vehicle for central locking and unlocking.</p>\n<p>⚠️ <strong>WARNING:</strong> This procedure does not allow you to program the remote controls with the vehicle’s immobilizer.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 01 ( </strong>“Remote Control Adaptation” from the drop-down list)</p>\n<p>Enter the number of keys to program, then click <strong>Save</strong>.<br/>Next, press the <strong>Unlock</strong> button on each remote control to be programmed for at least 1 second. A beep from the horn or the turn signals will confirm the procedure.<br/>All keys must be programmed in a single session, one after the other.<br/>Programming all keys must not take longer than <strong>15 seconds</strong>.<br/>You can add up to <strong>4 remote controls</strong>. If the <strong>[Test]</strong> and/or <strong>[Save]</strong> buttons are grayed out and unclickable, the module likely has all 4 slots filled; delete the remote controls using the <strong> “Reset Remote Controls”</strong> tutorial.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel01-10148edb.webp\"/></figure>","transporter-t5-rear-defrost-duration":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose:</strong> Selects rear defrost duration.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong> then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong> (“Rear Windshield Heating Activation Time” in the drop-down list)</p>\n<p><em>Set a value between <strong>1</strong> and <strong>254</strong> (from 0.66 min to 173 min)</em><br/><em>Default value is <strong>29</strong> (20 min)</em><br/><em><strong>254</strong> allows defrost to run all the time</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q1-937-049-C_Module09_Adaptation_Channel04-5d1fd686.webp\"/></figure>","transporter-t5-reset-keys":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose:</strong> Resets the settings for all remote controls associated with the vehicle.</p>\n<p><strong>⚠️ WARNING:</strong> After completing this procedure, all remote controls will be deleted and will need to be reprogrammed using the <strong>“How to Program a Remote Control”</strong> tutorial <strong>.</strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 00</strong></p>\n<p><em>Set the value to <strong>0</strong> and save</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel00-caced031.webp\"/></figure>","transporter-t5-selective-unlocking-all-doors":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose </strong>: To select the type of door opening after pressing the remote control. <br/><br/><strong>Selective:</strong> one press unlocks only the driver’s door, two presses unlocks all doors. <br/><strong>All doors:</strong> one press unlocks all doors.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on ” <strong>Coding- 07</strong>“.</p>\n<p><em>  Add <strong>+00001</strong> to the existing coding for all doors if you are in selective mode.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Coding-a046d403.webp\"/></figure>","transporter-t5-vehicle-lock-confirmation-beeps":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose </strong>: Activates beeps when vehicle is locked.  </p>\n<p><strong>Only for vehicles with alarm</strong> <br/>(1 beep for locking)  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 07 </strong>(“Locking Confirmation (Beep)” in the drop-down list)</p>\n<p>Set the value to <strong>1</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel07-586762e1.webp\"/></figure>","transporter-t5-vehicle-lock-confirmation-turn-signals":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose </strong>: activates turn signals when vehicle is locked.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 09 </strong>(“Locking Confirmation (Blink)” in the drop-down list)</p>\n<p>Set the value to <strong>1</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel09-5526f212.webp\"/></figure>","transporter-t5-vehicle-unlocking-confirmation-beeps":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_multivan_7h-3cbe9383.webp\"/></figure>\n<p><strong>Purpose </strong>: Activates beeps when vehicle is unlocked.  </p>\n<p><strong>Only for vehicles with alarm</strong> <br/>(2 beeps for unlocking)  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 06 </strong>(“Unlocking Confirmation (Beep)” in the drop-down list)</p>\n<p>Set the value to <strong>1</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel06-f9ca6e4a.webp\"/></figure>"};
